cat >> test/app.test.ts <<'EOF'

test("reviews: buyer can review once; others and bad input are rejected", async () => {
  const post = (token: string, id: string | number, body: unknown) =>
    fetch(`${base}/products/${id}/reviews`, { method: "POST", headers: { ...as(token), "content-type": "application/json" }, body: JSON.stringify(body) });

  assert.equal((await post("alice-token", 1, { rating: 5, body: "Great" })).status, 201);
  assert.equal((await post("alice-token", 1, { rating: 4, body: "Again" })).status, 409);
  // Bob never bought product 1
  const notBuyer = await post("bob-token", 1, { rating: 1, body: "Nope" });
  assert.equal(notBuyer.status, 403);
  assert.equal((await notBuyer.json()).error.code, "not_purchased");
  assert.equal((await post("alice-token", 1, { rating: 6, body: "x" })).status, 400);
  assert.equal((await post("alice-token", 3, { rating: 2.5, body: "x" })).status, 400);
  assert.equal((await post("alice-token", 3, { rating: 3, body: "  " })).status, 400);
  assert.equal((await post("alice-token", 3, { rating: 3 })).status, 400);
  assert.equal((await post("alice-token", 999, { rating: 3, body: "x" })).status, 404);
  assert.equal((await post("alice-token", "abc", { rating: 3, body: "x" })).status, 404);

  const list = await fetch(`${base}/products/1/reviews`, { headers: as("bob-token") });
  assert.equal(list.status, 200);
  const reviews = await list.json();
  assert.equal(reviews.length, 1);
  assert.equal(reviews[0].rating, 5);
  assert.equal((await fetch(`${base}/products/999/reviews`, { headers: as("bob-token") })).status, 404);
});

test("reviews: parallel duplicate posts create one review", async () => {
  const results = await Promise.all(Array.from({ length: 15 }, () =>
    fetch(`${base}/products/2/reviews`, { method: "POST", headers: { ...as("bob-token"), "content-type": "application/json" }, body: JSON.stringify({ rating: 4, body: "Nice mug" }) })));
  const statuses = results.map((r) => r.status).sort();
  assert.equal(statuses.filter((s) => s === 201).length, 1);
  assert.equal(statuses.filter((s) => s === 409).length, 14);
});
EOF
